              "course_id": "crs_1196",
              "distance_f": "10",
              "distance_y": "2205",
              "quote": "Highwaygrey likes fast ground and likes a stiff finish. He travels into it well and it seems to suit him this track - William Easterby, trainer's assistant, talking to Racing TV."
