          "comment": "Won this 12 months ago but slow ground seems preferable and a return to form is needed",
          "spotlight": "Now 3lb lower than when winning this 12 months ago (soft); however, he's failed to shine on either outing this year and slow ground, which seems unlikely to prevail today, is probably preferable.",
