              "distance_f": "14",
              "distance_y": "3081",
              "quote": "The first two home ran against each other at Doncaster and it wasn't total shock because Pole Star is a big raw horse and he'd won here before. I thought he was beat on the turn but once he got into a battle I thought he was in with a shout because he's that type of horse. Subjectivist was second in this race and we've won it a few times, and in the future we'll take the same line as the horses who ran in it before - Jock Bennett, trainer's assistant."
