          "comment": "C&D winner in 2022; yet to shine in five starts for this yard; first start since January",
          "spotlight": "C&D winner in 2022; yet to shine in five starts for this yard on AW; returns to turf and steps back up in trip on his first start since January.",
          "quotes": [
            {
              "date": "2022-04-21",
              "horse": "Evocative Spark",
              "horse_id": "hrs_26088307",
              "race": "Alan McGuiness And Robin Lunness Memorial Handicap",
              "race_id": "rac_10498397",
              "course": "Beverley",
              "course_id": "crs_156",
              "distance_f": "7.5",
              "distance_y": "1636",
              "quote": "Evocative Spark is a progressive colt and the draw beat him last time, he'd have been a good winner otherwise. He's one to look forward to. The Britannia would have to come into the reckoning, he'll get a mile and he likes fast ground. And there's a £75,000 seven-furlong handicap at Goodwood in late-May - George Boughey, trainer."
            }
          ],
          "stable_tour": [
            {
              "quote": "He won over 7½f for Hugo Palmer last year and I was delighted with his stable debut this month when second of 14 at Beverley, as it brought him on nicely. I found a lovely opportunity at Beverley last week and he ran out an impressive winner. He is a well-bred son of Frankel and we can now look to some nice handicaps like the Britannia or a 7f handicap at Newmarket on July Cup day. He is still a colt and there is more improvement to come from him. 27-04-22"
            }
          ],
