          "comment": "Exposed 9yo but made a solid start for this yard behind an all-the-way winner at Lingfield",
          "spotlight": "Exposed 9yo but made a solid start for this yard behind an all-the-way winner at Lingfield (good to firm); considered.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "A yard favourite who's called “the champ” for a reason. He's been nothing but a superstar, winning ten races. He loves the big tracks, like Newmarket and York, and never seems to run a bad race. Since Mia has been riding him for the last couple of seasons, he's been very consistent as she gets a good tune out of him. I've pitched him into some big handicaps this season and he's run creditably. There's a nice handicap in him and he deserves a big one. He's won on every ground but is probably best on good to firm. I'll probably target him at Newmarket in the next few weeks and then there's the Great St Wilfrid at Ripon. We're in the Racing League this year, and so is Mia, so there could be something there. 26-07-24"
            }
          ],
