          "comment": "3l third at Haydock last time; Jack Nicholls can now claim his 7lb",
          "spotlight": "Multiple winner who gave her running to finish a 3l third at Haydock last time; Jack Nicholls can claim his 7lb this time.",
          "quotes": [
            {
              "date": "2024-01-27",
              "horse": "Hurt You Never",
              "horse_id": "hrs_24907680",
              "race": "BetUK. It's Where The UK Bets Handicap",
              "race_id": "rac_11147994",
              "course": "Newcastle (AW)",
              "course_id": "crs_35178",
              "distance_f": "5",
              "distance_y": "1100",
              "quote": "She's a really game mare. I thought Hurt You Never might need the run but she showed she's in great form. Early on I thought I'd gone a bit quick but she just kept powering through - Mia Nicholls, jockey, talking to Sky Sports Racing."
            }
          ],
          "stable_tour": [
            {
              "quote": "She's been a superstar for us. She hasn't stopped winning and she's honest and tough. The soft ground wasn't ideal for her at Doncaster last week, but she was 4lb well in, so we gave it a go and she ran well to finish fourth behind Jojo Rabbit. She's easy to train and ride. She's won ten times and there'll come a point where the handicapper will have a say, but she'll be winning again. 26-07-24"
            }
          ],
