          "comment": "Placed in three starts since being well beaten on debut; off for 54 days; handicap debut",
          "spotlight": "Failed to beat a rival at Southwell (7f, AW) on her debut in December but she's been placed in three starts since, most recently when upped to this trip at Wolverhampton (AW) 54 days ago; switches back to turf for her handicap debut.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "She was second last time at Doncaster, beaten by a Frankel out of a Cheveley Park winner who cost 1,600,000gns [Alfareqa], so she ran a huge race. Her form is strong from Chelmsford too, as the filly who beat her [Hey Boo] was second in the Fred Darling. The third [Forty Years On] won a Doncaster novice on Lincoln day. I like her and I think she'll get a mile well. She's a good-sized filly and a nice one to follow for the year. I feel a mark of 75 is kind. She'll be out in early June and we'll take it from there. It would be nice to win a couple of races but the ultimate aim would be black type. 14-05-25"
            }
          ],
