          "comment": "Not at his best on last two starts; losing run stretches back to August 2021",
          "spotlight": "Returned from a break with two placed efforts at Wolverhampton and Ripon; less good twice since and a losing run stretching back to August 2021 hardly instills confidence.",
          "quotes": [
            {
              "date": "2021-08-18",
              "horse": "Arranmore",
              "horse_id": "hrs_18645515",
              "race": "Every Race Live On Racing TV Handicap (A Jockey Club Grassroots Middle Distance Qualifier)",
              "race_id": "rac_10268284",
              "course": "Carlisle",
              "course_id": "crs_208",
              "distance_f": "8",
              "distance_y": "1713",
              "quote": "Arranmore got a nice lead and when Cassy O came to me he dug deep. He's tough and genuine and he's going the right way - Shane Gray, jockey."
            },
            {
              "date": "2019-08-17",
              "horse": "Arranmore",
              "horse_id": "hrs_18645515",
              "race": "Matchbook Irish EBF Maiden (Plus 10 Race)",
              "race_id": "rac_9591075",
              "course": "Cork",
              "course_id": "crs_15496",
              "distance_f": "6",
              "distance_y": "1320",
              "quote": "Kevin [Manning] said it was a bit of a messy race. They split into two groups and there was no pace on his side. The horse on his outside brought him over to be as one for the last three furlongs but there was nothing to bring him along quick enough. I'm sure he'll be stepped up in class. He's been unlucky to bump into a real good horse first time out and he got mugged at Naas on his outside last time. He deserved today and is a lovely horse for the future for connections. He's got a great attitude and is a beautiful horse to deal with - Ger Flynn, representative for Jim Bolger, trainer of Arranmore"
            }
          ],
