          "comment": "Record over 7f on good to firm ground this year reads 114; major player despite wide draw",
          "spotlight": "Record over 7f on good to firm ground this year reads 114, winning over C&D in April and at Beverley last month with two of these behind; didn't enjoy the clearest of runs back there 11 days ago and a major player despite his wide draw.",
