          "comment": "0-16 in handicaps since despite a plummeting mark; plenty to prove after 190 days off",
          "spotlight": "Dual winner over 7f on turf/AW at the start of his career, but 0-16 in handicaps since despite a plummeting mark; plenty to prove after 190 days off.",
          "quotes": [],
          "stable_tour": [
            {
              "quote": "He runs in the colours of Constitution Hill's owner Michael Buckley, who was my first ever owner and a very dear friend. Michael is enjoying a good time as an owner not only with the Champion Hurdle winner, but a lovely horse called Florida with William Haggas and I think this is a very nice horse too. He won well at Wolverhampton last time over 7f. He will be ready by mid-April, but as he has only had two runs we will have to carry a penalty in a novice, which is not ideal but it is what it is. We will probably go for 7f again, but he will get further. I think we have a nice horse on our hands. 29-03-23"
            }
          ],
