          "comment": "Won over 2m5f at Wexford, rider's claim eases burden, rated 120, the one to beat",
          "spotlight": "Got off the mark at the second attempt over hurdles at Wexford (2m5f, good) 11 days ago, earning an official rating of 120; rider's claim eases his welter burden and he looks the one to beat provided this run doesn't come too soon.",
          "quotes": [
            {
              "date": "2025-07-04",
              "horse": "Kamikaz Du Plessis",
              "horse_id": "hrs_39826836",
              "race": "Shamrock Enterprises Maiden Hurdle",
              "race_id": "rac_11684985",
              "course": "Wexford",
              "course_id": "crs_5226",
              "distance_f": "21",
              "distance_y": "4570",
              "quote": "Kamizaz Du Plessis is a very slick jumper. He travelled well, he was borderline keen early but once we went on a little bit he was perfect. He's a nice horse and hopefully there will be more to come from him. We weren't worried about the step up in trip because he had stayed on well at Ballinrobe the last day. He put the race to bed fairly easy but I was probably there a little too soon and he was just green and ran around a bit. I think he can improve again because he is a nice horse and I got a nice feel from him - Jack Kennedy, jockey."
            }
          ],
