          "comment": "Well supported when winning easily on hurdles debut, this harder but don't discount",
          "spotlight": "Won a point-to-point in March and was well supported when scoring on her hurdles debut in a mares' maiden at Wexford (2m4f, good) in May by 18l; this is a better race but she can't be discounted.",
          "quotes": [
            {
              "date": "2025-05-17",
              "horse": "Kilbuny Supersonic",
              "horse_id": "hrs_39827039",
              "race": "Wexford Racecourse Mares Maiden Hurdle",
              "race_id": "rac_11644646",
              "course": "Wexford",
              "course_id": "crs_5226",
              "distance_f": "20",
              "distance_y": "4400",
              "quote": "We made plenty of use of Kilbuny Supersonic in her bumper and she ran well, but maybe was a bit flat after winning her point-to-point. She bucked out today and was going so quick. She never saw another rival and it was super. She gave me a great feeling when schooling over hurdles last week and it brought out extra improvement. She's a lovely mare and lots of good horses come out of the point-to-point track she won at - Luke Murphy, jockey, speaking to Racing TV."
            }
          ],
