              "course": "Thurles",
              "course_id": "crs_5148",
              "distance_f": "15.5",
              "distance_y": "3432",
              "quote": "It looked a nice opportunity for Purse Price. She's been consistent so it was nice to get her head in front. She was travelling and jumping well and made it fairly easy so it all went to plan. I'd imagine she can make her mark in handicaps and hopefully there's another race or two in her - Jack Kennedy, jockey."
