              "course_id": "crs_4758",
              "distance_f": "7",
              "distance_y": "1564",
              "quote": "PURRING ALONG was working the best she's ever worked the past week. We brought her up to the beach the other day and I don't think I've ever seen a horse so fresh so it was a good omen coming into today. She got a little nick one day out in the paddock so she hasn't ran in a few weeks. Easy ground and a good pace suits - Shane Duffy, trainer."
