          "comment": "Has held her own in 1m1f/1m2f handicaps without looking ahead of her mark",
          "spotlight": "1m maiden winner on good ground; has held her own in 1m1f/1m2f handicaps without looking ahead of her mark; stepping up in trip could bring her on; wore the hood last time.",
          "quotes": [
            {
              "date": "2025-05-18",
              "horse": "Sound Of Lightning",
              "horse_id": "hrs_42780997",
              "race": "Twydil/Clovelly Irish EBF Fillies Maiden",
              "race_id": "rac_11644594",
              "course": "Naas",
              "course_id": "crs_4992",
              "distance_f": "8",
              "distance_y": "1760",
              "quote": "Sound Of Lightning had a very good run the first day but ran with the choke out for the first few furlongs at Navan. We said we'd come back in trip and get her to relax early, which she did. She finished off nicely so it's nice to get her back on track. I think the better ground suited but getting her to switch off was more important than the ground. She has a great pedigree and you'd love to get a bit of black-type. We'll try and find a nice Listed race and she'll stay a mile and a quarter if she does things right - Donnacha O'Brien, trainer ."
            }
          ],
