          "comment": "3-23 on the Flat, good effort at Clonmel latest, this is tougher, big career best required",
          "spotlight": "Dual-purpose mare is 3-23 on the level; went close at Tramore (2m, good) on latest; handles most ground but this is a much tougher race and she'll need a big career best off this mark.",
          "quotes": [
            {
              "date": "2024-07-07",
              "horse": "Curious Bride",
              "horse_id": "hrs_20093423",
              "race": "Private Suites At Limerick Racecourse Handicap",
              "race_id": "rac_11334882",
              "course": "Limerick",
              "course_id": "crs_4888",
              "distance_f": "17",
              "distance_y": "3740",
              "quote": "Curious Bride stays well but Colin said she doesn't necessarily need to go that far. She had a going day today and we'll see what the handicapper does with her - Eamonn O'Connell, trainer"
            },
            {
              "date": "2021-01-18",
              "horse": "Curious Bride",
              "horse_id": "hrs_20093423",
              "race": "Play Ladbrokes 5-A-Side Maiden Hurdle",
              "race_id": "rac_10091237",
              "course": "Punchestown",
              "course_id": "crs_5070",
              "distance_f": "16",
              "distance_y": "3520",
              "quote": "Curious Bride had the experience which stood to her and she got into a lovely rhythm. She jumped well and galloped all the way to the line. The further she goes the better - Sean Flanagan, rider."
            }
          ],
