          "prev_owners": [
            {
              "owner": "Teme Valley Racing",
              "owner_id": "own_1163156",
              "change_date": "2022-09-01"
            }
          ],
          "comment": "Won a novice chase on latest, good run over C&D in May, in form and place chance",
          "spotlight": "Versatile sort; won a Tipperary novice chase on latest early this month; three solid runs on the Flat prior to that win, including a 5.25l third of 15 over C&D; is 2lb above his last win but he's in form and he has place claims.",
          "quotes": [
            {
              "date": "2025-07-01",
              "horse": "Dark Note",
              "horse_id": "hrs_26961305",
              "race": "Packie Downey Memorial Rated Novice Chase",
              "race_id": "rac_11683087",
              "course": "Tipperary",
              "course_id": "crs_5252",
              "distance_f": "19.5",
              "distance_y": "4335",
              "quote": "Dark Note is a great servant and has won now on the Flat, over hurdles and fences. He gives the owners a good day out every day he runs so he's a right little horse. You can be sure he'll be in Killarney and Galway and will keep mixing it. Cian was very happy with him today and thought the extra trip was a big plus to him which will open up a few more options. He was slower than the other horse at the last but had the Flat speed to quicken up well - Brian Slattery, trainer's assistant."
            },
            {
              "date": "2023-07-09",
              "horse": "Dark Note",
              "horse_id": "hrs_26961305",
              "race": "Killyhevlin Lakeside Hotel & Lodges Maiden Hurdle",
              "race_id": "rac_10983232",
              "course": "Sligo",
              "course_id": "crs_5122",
              "distance_f": "17",
              "distance_y": "3714",
              "quote": "Dark Note had a very good run last time. I knew Jack was under pressure when he came alongside me. He probably got a head in front of me but me fellow ran all the way to the line - Cian Quirke, rider."
            },
            {
              "date": "2022-06-20",
              "horse": "Dark Note",
              "horse_id": "hrs_26961305",
              "race": "John Madden & Sons Apprentice Claiming Race",
              "race_id": "rac_10600811",
              "course": "Ballinrobe",
              "course_id": "crs_4550",
              "distance_f": "9.5",
              "distance_y": "2105",
              "quote": "I was happy enough. Dark Note got a lovely position all the way around in the box seat. I got a lovely split but I probably went too early. He got very lairy when he got to the front, I could've covered him up for a bit longer.  But look he got the job done and he done it well - Jake Coen, jockey."
            }
          ],
