          "owner": "P Davies",
          "owner_id": "own_7480",
          "prev_trainers": [],
          "prev_owners": [],
          "comment": "8yo rated 135 over fences in pomp, decent run on Flat debut last month, may be vulnerable",
          "spotlight": "Rated 135 over fences at his peak; 8yo ran well enough on his belated Flat debut at Down Royal (1m5f, good) last month; shaped like this extra furlong would suit but he may be vulnerable to younger legs.",
          "quotes": [
            {
              "date": "2022-12-11",
              "horse": "Arctic Bresil",
              "horse_id": "hrs_27237763",
              "race": "Bar One Racing Maiden Hurdle",
              "race_id": "rac_10768095",
              "course": "Cork",
              "course_id": "crs_15496",
              "distance_f": "17",
              "distance_y": "3705",
              "quote": "I don't think we need to rush and there is the Grade 2 Moscow Flyer Hurdle at Punchestown in the middle of January and that might be the race for Arctic Bresil. He has a lot of pace so we will stick to two miles - Henry de Bromhead, trainer."
            }
          ],
          "stable_tour": [
            {
              "quote": "We liked him a lot last season but he disappointed us in his last two runs. He goes over fences now and the aim is to get him out in a beginners' chase over the next few weeks. His schooling has been really good and hopefully fences will help him fulfil his potential. 20-11-23"
            },
            {
              "quote": "He made a bright start to his career when beating the highly rated Mercurey at Cork in December, which didn't come as a surprise as he'd looked a nice prospect. On the back of that we sent him to Sandown for the Grade 1 Tolworth but he simply never turned up and Rachael [Blackmore] pulled him up before the second-last. It was a very disappointing effort and clearly not what he's capable of. The plan is to bring him back at the Fairyhouse festival. 01-03-23"
            }
          ],
