          "comment": "128 rated hurdler, Flat debutant, ground versatile and has potential, check market",
          "spotlight": "Two-time winning hurdler rated 128 in that sphere; won a Punchestown handicap hurdle when last seen in early May and now makes Flat debut; ground versatile and has potential but probably best watched unless the market speaks.",
          "quotes": [
            {
              "date": "2025-05-01",
              "horse": "Putapoundinthejar",
              "horse_id": "hrs_40225297",
              "race": "Specialist Group Handicap Hurdle",
              "race_id": "rac_11625952",
              "course": "Punchestown",
              "course_id": "crs_5070",
              "distance_f": "16.5",
              "distance_y": "3614",
              "quote": "I hope Putapoundinthejar will keep improving. He should make a chaser in time, he's a typical Walk In The Park, he can be a little on edge but as soon he's cantering he's very straightforward. He wants better ground and could head to Galway - Tony Martin, trainer, speaking to Racing TV"
            },
            {
              "date": "2025-01-21",
              "horse": "Putapoundinthejar",
              "horse_id": "hrs_40225297",
              "race": "Molson Coors Beverage Company Maiden Hurdle",
              "race_id": "rac_11524890",
              "course": "Down Royal",
              "course_id": "crs_4680",
              "distance_f": "17",
              "distance_y": "3773",
              "quote": "It has just taken a while for everything to fall into place. Putapoundinthejar is still relatively young and immature. Today's race turned into a great opportunity with Willie's not there. We always thought he was a nice young horse and we still do - Tony Martin, trainer."
            }
          ],
